export const FAMILY_CM: NistCatalogFamily = {"code":"CM","name":"Configuration Management","controls":[{"id":"CM-1","oscal_id":"cm-1","family":"CM","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> configuration management policy that:\n    <organization-defined parameter> configuration management policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the configuration management policy and the associated configuration management controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the configuration management policy and procedures; and\nc. Review and update the current configuration management:\n  Review and update the current configuration management:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Configuration management policy and procedures address the controls in the CM family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of configuration management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to configuration management policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"cm-1_prm_1","label":"organization-defined personnel or roles"},{"id":"cm-01_odp.01","label":"personnel or roles"},{"id":"cm-01_odp.02","label":"personnel or roles"},{"id":"cm-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"cm-01_odp.04","label":"official"},{"id":"cm-01_odp.05","label":"frequency"},{"id":"cm-01_odp.06","label":"events"},{"id":"cm-01_odp.07","label":"frequency"},{"id":"cm-01_odp.08","label":"events"}],"objectives":[{"id":"cm-1_obj.a-1","label":"CM-01a.[01]","text":"a configuration management policy is developed and documented;"},{"id":"cm-1_obj.a-2","label":"CM-01a.[02]","text":"the configuration management policy is disseminated to {{ insert: param, cm-01_odp.01 }};"},{"id":"cm-1_obj.a-3","label":"CM-01a.[03]","text":"configuration management procedures to facilitate the implementation of the configuration management policy and associated configuration management controls are developed and documented;"},{"id":"cm-1_obj.a-4","label":"CM-01a.[04]","text":"the configuration management procedures are disseminated to {{ insert: param, cm-01_odp.02 }};"},{"id":"cm-1_obj.a.1.a-1","label":"CM-01a.01(a)[01]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses purpose;"},{"id":"cm-1_obj.a.1.a-2","label":"CM-01a.01(a)[02]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses scope;"},{"id":"cm-1_obj.a.1.a-3","label":"CM-01a.01(a)[03]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses roles;"},{"id":"cm-1_obj.a.1.a-4","label":"CM-01a.01(a)[04]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses responsibilities;"},{"id":"cm-1_obj.a.1.a-5","label":"CM-01a.01(a)[05]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses management commitment;"},{"id":"cm-1_obj.a.1.a-6","label":"CM-01a.01(a)[06]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses coordination among organizational entities;"},{"id":"cm-1_obj.a.1.a-7","label":"CM-01a.01(a)[07]","text":"the {{ insert: param, cm-01_odp.03 }} of the configuration management policy addresses compliance;"},{"id":"cm-1_obj.a.1.b","label":"CM-01a.01(b)","text":"the configuration management policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"cm-1_obj.b","label":"CM-01b.","text":"the {{ insert: param, cm-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the configuration management policy and procedures;"},{"id":"cm-1_obj.c.1-1","label":"CM-01c.01[01]","text":"the current configuration management policy is reviewed and updated {{ insert: param, cm-01_odp.05 }};"},{"id":"cm-1_obj.c.1-2","label":"CM-01c.01[02]","text":"the current configuration management policy is reviewed and updated following {{ insert: param, cm-01_odp.06 }};"},{"id":"cm-1_obj.c.2-1","label":"CM-01c.02[01]","text":"the current configuration management procedures are reviewed and updated {{ insert: param, cm-01_odp.07 }};"},{"id":"cm-1_obj.c.2-2","label":"CM-01c.02[02]","text":"the current configuration management procedures are reviewed and updated following {{ insert: param, cm-01_odp.08 }}."}],"methods":[{"method":"examine","label":"CM-01-Examine"},{"method":"interview","label":"CM-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SA-8","SI-12"]},{"id":"CM-2","oscal_id":"cm-2","family":"CM","title":"Baseline Configuration","statement":"a. Develop, document, and maintain under configuration control, a current baseline configuration of the system; and\nb. Review and update the baseline configuration of the system:\n  Review and update the baseline configuration of the system:\n  1. <frequency>;\n  2. When required due to <circumstances> ; and\n  3. When system components are installed or upgraded.","supplemental_guidance":"Baseline configurations for systems and system components include connectivity, operational, and communications aspects of systems. Baseline configurations are documented, formally reviewed, and agreed-upon specifications for systems or configuration items within those systems. Baseline configurations serve as a basis for future builds, releases, or changes to systems and include security and privacy control implementations, operational procedures, information about system components, network topology, and logical placement of components in the system architecture. Maintaining baseline configurations requires creating new baselines as organizational systems change over time. Baseline configurations of systems reflect the current enterprise architecture.","implementation_level":"organization","parameters":[{"id":"cm-02_odp.01","label":"frequency"},{"id":"cm-02_odp.02","label":"circumstances"}],"objectives":[{"id":"cm-2_obj.a-1","label":"CM-02a.[01]","text":"a current baseline configuration of the system is developed and documented;"},{"id":"cm-2_obj.a-2","label":"CM-02a.[02]","text":"a current baseline configuration of the system is maintained under configuration control;"},{"id":"cm-2_obj.b.1","label":"CM-02b.01","text":"the baseline configuration of the system is reviewed and updated {{ insert: param, cm-02_odp.01 }};"},{"id":"cm-2_obj.b.2","label":"CM-02b.02","text":"the baseline configuration of the system is reviewed and updated when required due to {{ insert: param, cm-02_odp.02 }};"},{"id":"cm-2_obj.b.3","label":"CM-02b.03","text":"the baseline configuration of the system is reviewed and updated when system components are installed or upgraded."}],"methods":[{"method":"examine","label":"CM-02-Examine"},{"method":"interview","label":"CM-02-Interview"},{"method":"test","label":"CM-02-Test"}],"references":[{"title":"SP 800-124"},{"title":"SP 800-128"}],"related_controls":["AC-19","AU-6","CA-9","CM-1","CM-3","CM-5","CM-6","CM-8","CM-9","CP-9","CP-10","CP-12","MA-2","PL-8","PM-5","SA-8","SA-10","SA-15","SC-18"],"enhancements":[{"id":"CM-2(1)","oscal_id":"cm-2.1","family":"CM","title":"Reviews and Updates","statement":"","is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(2)","oscal_id":"cm-2.2","family":"CM","title":"Automation Support for Accuracy and Currency","statement":"Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms that help organizations maintain consistent baseline configurations for systems include configuration management tools, hardware, software, firmware inventory tools, and network management tools. Automated tools can be used at the organization level, mission and business process level, or system level on workstations, servers, notebook computers, network components, or mobile devices. Tools can be used to track version numbers on operating systems, applications, types of software installed, and current patch levels. Automation support for accuracy and currency can be satisfied by the implementation of [CM-8(2)](#cm-8.2) for organizations that combine system component inventory and baseline configuration activities.","implementation_level":"organization","parameters":[{"id":"cm-02.02_odp","label":"automated mechanisms"}],"objectives":[{"id":"cm-2.2_obj-1","label":"CM-02(02)[01]","text":"the currency of the baseline configuration of the system is maintained using {{ insert: param, cm-02.02_odp }};"},{"id":"cm-2.2_obj-2","label":"CM-02(02)[02]","text":"the completeness of the baseline configuration of the system is maintained using {{ insert: param, cm-02.02_odp }};"},{"id":"cm-2.2_obj-3","label":"CM-02(02)[03]","text":"the accuracy of the baseline configuration of the system is maintained using {{ insert: param, cm-02.02_odp }};"},{"id":"cm-2.2_obj-4","label":"CM-02(02)[04]","text":"the availability of the baseline configuration of the system is maintained using {{ insert: param, cm-02.02_odp }}."}],"methods":[{"method":"examine","label":"CM-02(02)-Examine"},{"method":"interview","label":"CM-02(02)-Interview"},{"method":"test","label":"CM-02(02)-Test"}],"related_controls":["CM-7","IA-3","RA-5"],"is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(3)","oscal_id":"cm-2.3","family":"CM","title":"Retention of Previous Configurations","statement":"Retain <number> of previous versions of baseline configurations of the system to support rollback.","supplemental_guidance":"Retaining previous versions of baseline configurations to support rollback include hardware, software, firmware, configuration files, configuration records, and associated documentation.","implementation_level":"organization","parameters":[{"id":"cm-02.03_odp","label":"number"}],"methods":[{"method":"examine","label":"CM-02(03)-Examine"},{"method":"interview","label":"CM-02(03)-Interview"},{"method":"test","label":"CM-02(03)-Test"}],"is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(4)","oscal_id":"cm-2.4","family":"CM","title":"Unauthorized Software","statement":"","is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(5)","oscal_id":"cm-2.5","family":"CM","title":"Authorized Software","statement":"","is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(6)","oscal_id":"cm-2.6","family":"CM","title":"Development and Test Environments","statement":"Maintain a baseline configuration for system development and test environments that is managed separately from the operational baseline configuration.","supplemental_guidance":"Establishing separate baseline configurations for development, testing, and operational environments protects systems from unplanned or unexpected events related to development and testing activities. Separate baseline configurations allow organizations to apply the configuration management that is most appropriate for each type of configuration. For example, the management of operational configurations typically emphasizes the need for stability, while the management of development or test configurations requires greater flexibility. Configurations in the test environment mirror configurations in the operational environment to the extent practicable so that the results of the testing are representative of the proposed changes to the operational systems. Separate baseline configurations do not necessarily require separate physical environments.","implementation_level":"organization","objectives":[{"id":"cm-2.6_obj-1","label":"CM-02(06)[01]","text":"a baseline configuration for system development environments that is managed separately from the operational baseline configuration is maintained;"},{"id":"cm-2.6_obj-2","label":"CM-02(06)[02]","text":"a baseline configuration for test environments that is managed separately from the operational baseline configuration is maintained."}],"methods":[{"method":"examine","label":"CM-02(06)-Examine"},{"method":"interview","label":"CM-02(06)-Interview"},{"method":"test","label":"CM-02(06)-Test"}],"related_controls":["CM-4","SC-3","SC-7"],"is_enhancement":true,"parent_id":"CM-2"},{"id":"CM-2(7)","oscal_id":"cm-2.7","family":"CM","title":"Configure Systems and Components for High-risk Areas","statement":"(a) Issue <systems or system components> with <configurations> to individuals traveling to locations that the organization deems to be of significant risk; and\n(b) Apply the following controls to the systems or components when the individuals return from travel: <controls>.","supplemental_guidance":"When it is known that systems or system components will be in high-risk areas external to the organization, additional controls may be implemented to counter the increased threat in such areas. For example, organizations can take actions for notebook computers used by individuals departing on and returning from travel. Actions include determining the locations that are of concern, defining the required configurations for the components, ensuring that components are configured as intended before travel is initiated, and applying controls to the components after travel is completed. Specially configured notebook computers include computers with sanitized hard drives, limited applications, and more stringent configuration settings. Controls applied to mobile devices upon return from travel include examining the mobile device for signs of physical tampering and purging and reimaging disk drives. Protecting information that resides on mobile devices is addressed in the [MP](#mp) (Media Protection) family.","implementation_level":"organization","parameters":[{"id":"cm-02.07_odp.01","label":"systems or system components"},{"id":"cm-02.07_odp.02","label":"configurations"},{"id":"cm-02.07_odp.03","label":"controls"}],"objectives":[{"id":"cm-2.7_obj.a","label":"CM-02(07)(a)","text":"{{ insert: param, cm-02.07_odp.01 }} with {{ insert: param, cm-02.07_odp.02 }} are issued to individuals traveling to locations that the organization deems to be of significant risk;"},{"id":"cm-2.7_obj.b","label":"CM-02(07)(b)","text":"{{ insert: param, cm-02.07_odp.03 }} are applied to the systems or system components when the individuals return from travel."}],"methods":[{"method":"examine","label":"CM-02(07)-Examine"},{"method":"interview","label":"CM-02(07)-Interview"},{"method":"test","label":"CM-02(07)-Test"}],"related_controls":["MP-4","MP-5"],"is_enhancement":true,"parent_id":"CM-2"}]},{"id":"CM-3","oscal_id":"cm-3","family":"CM","title":"Configuration Change Control","statement":"a. Determine and document the types of changes to the system that are configuration-controlled;\nb. Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses;\nc. Document configuration change decisions associated with the system;\nd. Implement approved configuration-controlled changes to the system;\ne. Retain records of configuration-controlled changes to the system for <time period>;\nf. Monitor and review activities associated with configuration-controlled changes to the system; and\ng. Coordinate and provide oversight for configuration change control activities through <configuration change control element> that convenes <organization-defined parameter>.","supplemental_guidance":"Configuration change control for organizational systems involves the systematic proposal, justification, implementation, testing, review, and disposition of system changes, including system upgrades and modifications. Configuration change control includes changes to baseline configurations, configuration items of systems, operational procedures, configuration settings for system components, remediate vulnerabilities, and unscheduled or unauthorized changes. Processes for managing configuration changes to systems include Configuration Control Boards or Change Advisory Boards that review and approve proposed changes. For changes that impact privacy risk, the senior agency official for privacy updates privacy impact assessments and system of records notices. For new systems or major upgrades, organizations consider including representatives from the development organizations on the Configuration Control Boards or Change Advisory Boards. Auditing of changes includes activities before and after changes are made to systems and the auditing activities required to implement such changes. See also [SA-10](#sa-10).","implementation_level":"organization","parameters":[{"id":"cm-03_odp.01","label":"time period"},{"id":"cm-03_odp.02","label":"configuration change control element"},{"id":"cm-03_odp.03","label":"","choices":["{{ insert: param, cm-03_odp.04 }} ","when {{ insert: param, cm-03_odp.05 }} "],"how_many":"one-or-more"},{"id":"cm-03_odp.04","label":"frequency"},{"id":"cm-03_odp.05","label":"configuration change conditions"}],"objectives":[{"id":"cm-3_obj.a","label":"CM-03a.","text":"the types of changes to the system that are configuration-controlled are determined and documented;"},{"id":"cm-3_obj.b-1","label":"CM-03b.[01]","text":"proposed configuration-controlled changes to the system are reviewed;"},{"id":"cm-3_obj.b-2","label":"CM-03b.[02]","text":"proposed configuration-controlled changes to the system are approved or disapproved with explicit consideration for security and privacy impact analyses;"},{"id":"cm-3_obj.c","label":"CM-03c.","text":"configuration change decisions associated with the system are documented;"},{"id":"cm-3_obj.d","label":"CM-03d.","text":"approved configuration-controlled changes to the system are implemented;"},{"id":"cm-3_obj.e","label":"CM-03e.","text":"records of configuration-controlled changes to the system are retained for {{ insert: param, cm-03_odp.01 }};"},{"id":"cm-3_obj.f-1","label":"CM-03f.[01]","text":"activities associated with configuration-controlled changes to the system are monitored;"},{"id":"cm-3_obj.f-2","label":"CM-03f.[02]","text":"activities associated with configuration-controlled changes to the system are reviewed;"},{"id":"cm-3_obj.g-1","label":"CM-03g.[01]","text":"configuration change control activities are coordinated and overseen by {{ insert: param, cm-03_odp.02 }};"},{"id":"cm-3_obj.g-2","label":"CM-03g.[02]","text":"the configuration control element convenes {{ insert: param, cm-03_odp.03 }}."}],"methods":[{"method":"examine","label":"CM-03-Examine"},{"method":"interview","label":"CM-03-Interview"},{"method":"test","label":"CM-03-Test"}],"references":[{"title":"SP 800-124"},{"title":"SP 800-128"},{"title":"IR 8062"}],"related_controls":["CA-7","CM-2","CM-4","CM-5","CM-6","CM-9","CM-11","IA-3","MA-2","PE-16","PT-6","RA-8","SA-8","SA-10","SC-28","SC-34","SC-37","SI-2","SI-3","SI-4","SI-7","SI-10","SR-11"],"enhancements":[{"id":"CM-3(1)","oscal_id":"cm-3.1","family":"CM","title":"Automated Documentation, Notification, and Prohibition of Changes","statement":"Use <automated mechanisms> to:\n(a) Document proposed changes to the system;\n(b) Notify <approval authorities> of proposed changes to the system and request change approval;\n(c) Highlight proposed changes to the system that have not been approved or disapproved within <time period>;\n(d) Prohibit changes to the system until designated approvals are received;\n(e) Document all changes to the system; and\n(f) Notify <personnel> when approved changes to the system are completed.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"cm-03.01_odp.01","label":"automated mechanisms"},{"id":"cm-03.01_odp.02","label":"approval authorities"},{"id":"cm-03.01_odp.03","label":"time period"},{"id":"cm-03.01_odp.04","label":"personnel"}],"objectives":[{"id":"cm-3.1_obj.a","label":"CM-03(01)(a)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to document proposed changes to the system;"},{"id":"cm-3.1_obj.b","label":"CM-03(01)(b)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to notify {{ insert: param, cm-03.01_odp.02 }} of proposed changes to the system and request change approval;"},{"id":"cm-3.1_obj.c","label":"CM-03(01)(c)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to highlight proposed changes to the system that have not been approved or disapproved within {{ insert: param, cm-03.01_odp.03 }};"},{"id":"cm-3.1_obj.d","label":"CM-03(01)(d)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to prohibit changes to the system until designated approvals are received;"},{"id":"cm-3.1_obj.e","label":"CM-03(01)(e)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to document all changes to the system;"},{"id":"cm-3.1_obj.f","label":"CM-03(01)(f)","text":"{{ insert: param, cm-03.01_odp.01 }} are used to notify {{ insert: param, cm-03.01_odp.04 }} when approved changes to the system are completed."}],"methods":[{"method":"examine","label":"CM-03(01)-Examine"},{"method":"interview","label":"CM-03(01)-Interview"},{"method":"test","label":"CM-03(01)-Test"}],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(2)","oscal_id":"cm-3.2","family":"CM","title":"Testing, Validation, and Documentation of Changes","statement":"Test, validate, and document changes to the system before finalizing the implementation of the changes.","supplemental_guidance":"Changes to systems include modifications to hardware, software, or firmware components and configuration settings defined in [CM-6](#cm-6) . Organizations ensure that testing does not interfere with system operations that support organizational mission and business functions. Individuals or groups conducting tests understand security and privacy policies and procedures, system security and privacy policies and procedures, and the health, safety, and environmental risks associated with specific facilities or processes. Operational systems may need to be taken offline, or replicated to the extent feasible, before testing can be conducted. If systems must be taken offline for testing, the tests are scheduled to occur during planned system outages whenever possible. If the testing cannot be conducted on operational systems, organizations employ compensating controls.","implementation_level":"organization","objectives":[{"id":"cm-3.2_obj-1","label":"CM-03(02)[01]","text":"changes to the system are tested before finalizing the implementation of the changes;"},{"id":"cm-3.2_obj-2","label":"CM-03(02)[02]","text":"changes to the system are validated before finalizing the implementation of the changes;"},{"id":"cm-3.2_obj-3","label":"CM-03(02)[03]","text":"changes to the system are documented before finalizing the implementation of the changes."}],"methods":[{"method":"examine","label":"CM-03(02)-Examine"},{"method":"interview","label":"CM-03(02)-Interview"},{"method":"test","label":"CM-03(02)-Test"}],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(3)","oscal_id":"cm-3.3","family":"CM","title":"Automated Change Implementation","statement":"Implement changes to the current system baseline and deploy the updated baseline across the installed base using <automated mechanisms>.","supplemental_guidance":"Automated tools can improve the accuracy, consistency, and availability of configuration baseline information. Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization.","implementation_level":"organization","parameters":[{"id":"cm-03.03_odp","label":"automated mechanisms"}],"objectives":[{"id":"cm-3.3_obj-1","label":"CM-03(03)[01]","text":"changes to the current system baseline are implemented using {{ insert: param, cm-03.03_odp }};"},{"id":"cm-3.3_obj-2","label":"CM-03(03)[02]","text":"the updated baseline is deployed across the installed base using {{ insert: param, cm-03.03_odp }}."}],"methods":[{"method":"examine","label":"CM-03(03)-Examine"},{"method":"interview","label":"CM-03(03)-Interview"},{"method":"test","label":"CM-03(03)-Test"}],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(4)","oscal_id":"cm-3.4","family":"CM","title":"Security and Privacy Representatives","statement":"Require <organization-defined security and privacy representatives> to be members of the <configuration change control element>.","supplemental_guidance":"Information security and privacy representatives include system security officers, senior agency information security officers, senior agency officials for privacy, or system privacy officers. Representation by personnel with information security and privacy expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems. The configuration change control element referred to in the second organization-defined parameter reflects the change control elements defined by organizations in [CM-3g](#cm-3_smt.g).","implementation_level":"organization","parameters":[{"id":"cm-3.4_prm_1","label":"organization-defined security and privacy representatives"},{"id":"cm-03.04_odp.01","label":"security representatives"},{"id":"cm-03.04_odp.02","label":"privacy representatives"},{"id":"cm-03.04_odp.03","label":"configuration change control element"}],"objectives":[{"id":"cm-3.4_obj-1","label":"CM-03(04)[01]","text":"{{ insert: param, cm-03.04_odp.01 }} are required to be members of the {{ insert: param, cm-03.04_odp.03 }};"},{"id":"cm-3.4_obj-2","label":"CM-03(04)[02]","text":"{{ insert: param, cm-03.04_odp.02 }} are required to be members of the {{ insert: param, cm-03.04_odp.03 }}."}],"methods":[{"method":"examine","label":"CM-03(04)-Examine"},{"method":"interview","label":"CM-03(04)-Interview"},{"method":"test","label":"CM-03(04)-Test"}],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(5)","oscal_id":"cm-3.5","family":"CM","title":"Automated Security Response","statement":"Implement the following security responses automatically if baseline configurations are changed in an unauthorized manner: <security responses>.","supplemental_guidance":"Automated security responses include halting selected system functions, halting system processing, and issuing alerts or notifications to organizational personnel when there is an unauthorized modification of a configuration item.","implementation_level":"system","parameters":[{"id":"cm-03.05_odp","label":"security responses"}],"methods":[{"method":"examine","label":"CM-03(05)-Examine"},{"method":"interview","label":"CM-03(05)-Interview"},{"method":"test","label":"CM-03(05)-Test"}],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(6)","oscal_id":"cm-3.6","family":"CM","title":"Cryptography Management","statement":"Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: <controls>.","supplemental_guidance":"The controls referenced in the control enhancement refer to security and privacy controls from the control catalog. Regardless of the cryptographic mechanisms employed, processes and procedures are in place to manage those mechanisms. For example, if system components use certificates for identification and authentication, a process is implemented to address the expiration of those certificates.","implementation_level":"organization","parameters":[{"id":"cm-03.06_odp","label":"controls"}],"methods":[{"method":"examine","label":"CM-03(06)-Examine"},{"method":"interview","label":"CM-03(06)-Interview"},{"method":"test","label":"CM-03(06)-Test"}],"related_controls":["SC-12"],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(7)","oscal_id":"cm-3.7","family":"CM","title":"Review System Changes","statement":"Review changes to the system <frequency> or when <circumstances> to determine whether unauthorized changes have occurred.","supplemental_guidance":"Indications that warrant a review of changes to the system and the specific circumstances justifying such reviews may be obtained from activities carried out by organizations during the configuration change process or continuous monitoring process.","implementation_level":"organization","parameters":[{"id":"cm-03.07_odp.01","label":"frequency"},{"id":"cm-03.07_odp.02","label":"circumstances"}],"methods":[{"method":"examine","label":"CM-03(07)-Examine"},{"method":"interview","label":"CM-03(07)-Interview"},{"method":"test","label":"CM-03(07)-Test"}],"related_controls":["AU-6","AU-7","CM-3"],"is_enhancement":true,"parent_id":"CM-3"},{"id":"CM-3(8)","oscal_id":"cm-3.8","family":"CM","title":"Prevent or Restrict Configuration Changes","statement":"Prevent or restrict changes to the configuration of the system under the following circumstances: <circumstances>.","supplemental_guidance":"System configuration changes can adversely affect critical system security and privacy functionality. Change restrictions can be enforced through automated mechanisms.","implementation_level":"system","parameters":[{"id":"cm-03.08_odp","label":"circumstances"}],"methods":[{"method":"examine","label":"CM-03(08)-Examine"}],"is_enhancement":true,"parent_id":"CM-3"}]},{"id":"CM-4","oscal_id":"cm-4","family":"CM","title":"Impact Analyses","statement":"Analyze changes to the system to determine potential security and privacy impacts prior to change implementation.","supplemental_guidance":"Organizational personnel with security or privacy responsibilities conduct impact analyses. Individuals conducting impact analyses possess the necessary skills and technical expertise to analyze the changes to systems as well as the security or privacy ramifications. Impact analyses include reviewing security and privacy plans, policies, and procedures to understand control requirements; reviewing system design documentation and operational procedures to understand control implementation and how specific system changes might affect the controls; reviewing the impact of changes on organizational supply chain partners with stakeholders; and determining how potential changes to a system create new risks to the privacy of individuals and the ability of implemented controls to mitigate those risks. Impact analyses also include risk assessments to understand the impact of the changes and determine if additional controls are required.","implementation_level":"organization","objectives":[{"id":"cm-4_obj-1","label":"CM-04[01]","text":"changes to the system are analyzed to determine potential security impacts prior to change implementation;"},{"id":"cm-4_obj-2","label":"CM-04[02]","text":"changes to the system are analyzed to determine potential privacy impacts prior to change implementation."}],"methods":[{"method":"examine","label":"CM-04-Examine"},{"method":"interview","label":"CM-04-Interview"},{"method":"test","label":"CM-04-Test"}],"references":[{"title":"SP 800-128"}],"related_controls":["CA-7","CM-3","CM-8","CM-9","MA-2","RA-3","RA-5","RA-8","SA-5","SA-8","SA-10","SI-2"],"enhancements":[{"id":"CM-4(1)","oscal_id":"cm-4.1","family":"CM","title":"Separate Test Environments","statement":"Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice.","supplemental_guidance":"A separate test environment requires an environment that is physically or logically separate and distinct from the operational environment. The separation is sufficient to ensure that activities in the test environment do not impact activities in the operational environment and that information in the operational environment is not inadvertently transmitted to the test environment. Separate environments can be achieved by physical or logical means. If physically separate test environments are not implemented, organizations determine the strength of mechanism required when implementing logical separation.","implementation_level":"organization","objectives":[{"id":"cm-4.1_obj-1","label":"CM-04(01)[01]","text":"changes to the system are analyzed in a separate test environment before implementation in an operational environment;"},{"id":"cm-4.1_obj-2","label":"CM-04(01)[02]","text":"changes to the system are analyzed for security impacts due to flaws;"},{"id":"cm-4.1_obj-3","label":"CM-04(01)[03]","text":"changes to the system are analyzed for privacy impacts due to flaws;"},{"id":"cm-4.1_obj-4","label":"CM-04(01)[04]","text":"changes to the system are analyzed for security impacts due to weaknesses;"},{"id":"cm-4.1_obj-5","label":"CM-04(01)[05]","text":"changes to the system are analyzed for privacy impacts due to weaknesses;"},{"id":"cm-4.1_obj-6","label":"CM-04(01)[06]","text":"changes to the system are analyzed for security impacts due to incompatibility;"},{"id":"cm-4.1_obj-7","label":"CM-04(01)[07]","text":"changes to the system are analyzed for privacy impacts due to incompatibility;"},{"id":"cm-4.1_obj-8","label":"CM-04(01)[08]","text":"changes to the system are analyzed for security impacts due to intentional malice;"},{"id":"cm-4.1_obj-9","label":"CM-04(01)[09]","text":"changes to the system are analyzed for privacy impacts due to intentional malice."}],"methods":[{"method":"examine","label":"CM-04(01)-Examine"},{"method":"interview","label":"CM-04(01)-Interview"},{"method":"test","label":"CM-04(01)-Test"}],"related_controls":["SA-11","SC-7"],"is_enhancement":true,"parent_id":"CM-4"},{"id":"CM-4(2)","oscal_id":"cm-4.2","family":"CM","title":"Verification of Controls","statement":"After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system.","supplemental_guidance":"Implementation in this context refers to installing changed code in the operational system that may have an impact on security or privacy controls.","implementation_level":"organization","objectives":[{"id":"cm-4.2_obj-1","label":"CM-04(02)[01]","text":"the impacted controls are implemented correctly with regard to meeting the security requirements for the system after system changes;"},{"id":"cm-4.2_obj-2","label":"CM-04(02)[02]","text":"the impacted controls are implemented correctly with regard to meeting the privacy requirements for the system after system changes;"},{"id":"cm-4.2_obj-3","label":"CM-04(02)[03]","text":"the impacted controls are operating as intended with regard to meeting the security requirements for the system after system changes;"},{"id":"cm-4.2_obj-4","label":"CM-04(02)[04]","text":"the impacted controls are operating as intended with regard to meeting the privacy requirements for the system after system changes;"},{"id":"cm-4.2_obj-5","label":"CM-04(02)[05]","text":"the impacted controls are producing the desired outcome with regard to meeting the security requirements for the system after system changes;"},{"id":"cm-4.2_obj-6","label":"CM-04(02)[06]","text":"the impacted controls are producing the desired outcome with regard to meeting the privacy requirements for the system after system changes."}],"methods":[{"method":"examine","label":"CM-04(02)-Examine"},{"method":"interview","label":"CM-04(02)-Interview"},{"method":"test","label":"CM-04(02)-Test"}],"related_controls":["SA-11","SC-3","SI-6"],"is_enhancement":true,"parent_id":"CM-4"}]},{"id":"CM-5","oscal_id":"cm-5","family":"CM","title":"Access Restrictions for Change","statement":"Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system.","supplemental_guidance":"Changes to the hardware, software, or firmware components of systems or the operational procedures related to the system can potentially have significant effects on the security of the systems or individuals’ privacy. Therefore, organizations permit only qualified and authorized individuals to access systems for purposes of initiating changes. Access restrictions include physical and logical access controls (see [AC-3](#ac-3) and [PE-3](#pe-3) ), software libraries, workflow automation, media libraries, abstract layers (i.e., changes implemented into external interfaces rather than directly into systems), and change windows (i.e., changes occur only during specified times).","implementation_level":"organization","objectives":[{"id":"cm-5_obj-1","label":"CM-05[01]","text":"physical access restrictions associated with changes to the system are defined and documented;"},{"id":"cm-5_obj-2","label":"CM-05[02]","text":"physical access restrictions associated with changes to the system are approved;"},{"id":"cm-5_obj-3","label":"CM-05[03]","text":"physical access restrictions associated with changes to the system are enforced;"},{"id":"cm-5_obj-4","label":"CM-05[04]","text":"logical access restrictions associated with changes to the system are defined and documented;"},{"id":"cm-5_obj-5","label":"CM-05[05]","text":"logical access restrictions associated with changes to the system are approved;"},{"id":"cm-5_obj-6","label":"CM-05[06]","text":"logical access restrictions associated with changes to the system are enforced."}],"methods":[{"method":"examine","label":"CM-05-Examine"},{"method":"interview","label":"CM-05-Interview"},{"method":"test","label":"CM-05-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 186-4"}],"related_controls":["AC-3","AC-5","AC-6","CM-9","PE-3","SC-28","SC-34","SC-37","SI-2","SI-10"],"enhancements":[{"id":"CM-5(1)","oscal_id":"cm-5.1","family":"CM","title":"Automated Access Enforcement and Audit Records","statement":"(a) Enforce access restrictions using <automated mechanisms> ; and\n(b) Automatically generate audit records of the enforcement actions.","supplemental_guidance":"Organizations log system accesses associated with applying configuration changes to ensure that configuration change control is implemented and to support after-the-fact actions should organizations discover any unauthorized changes.","implementation_level":"system","parameters":[{"id":"cm-05.01_odp","label":"automated mechanisms"}],"objectives":[{"id":"cm-5.1_obj.a","label":"CM-05(01)(a)","text":"access restrictions for change are enforced using {{ insert: param, cm-05.01_odp }};"},{"id":"cm-5.1_obj.b","label":"CM-05(01)(b)","text":"audit records of enforcement actions are automatically generated."}],"methods":[{"method":"examine","label":"CM-05(01)-Examine"},{"method":"interview","label":"CM-05(01)-Interview"},{"method":"test","label":"CM-05(01)-Test"}],"related_controls":["AU-2","AU-6","AU-7","AU-12","CM-6","CM-11","SI-12"],"is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(2)","oscal_id":"cm-5.2","family":"CM","title":"Review System Changes","statement":"","is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(3)","oscal_id":"cm-5.3","family":"CM","title":"Signed Components","statement":"","is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(4)","oscal_id":"cm-5.4","family":"CM","title":"Dual Authorization","statement":"Enforce dual authorization for implementing changes to <organization-defined system components and system-level information>.","supplemental_guidance":"Organizations employ dual authorization to help ensure that any changes to selected system components and information cannot occur unless two qualified individuals approve and implement such changes. The two individuals possess the skills and expertise to determine if the proposed changes are correct implementations of approved changes. The individuals are also accountable for the changes. Dual authorization may also be known as two-person control. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals. System-level information includes operational procedures.","implementation_level":"organization","parameters":[{"id":"cm-5.4_prm_1","label":"organization-defined system components and system-level information"},{"id":"cm-05.04_odp.01","label":"system components"},{"id":"cm-05.04_odp.02","label":"system-level information"}],"objectives":[{"id":"cm-5.4_obj-1","label":"CM-05(04)[01]","text":"dual authorization for implementing changes to {{ insert: param, cm-05.04_odp.01 }} is enforced;"},{"id":"cm-5.4_obj-2","label":"CM-05(04)[02]","text":"dual authorization for implementing changes to {{ insert: param, cm-05.04_odp.02 }} is enforced."}],"methods":[{"method":"examine","label":"CM-05(04)-Examine"},{"method":"interview","label":"CM-05(04)-Interview"},{"method":"test","label":"CM-05(04)-Test"}],"related_controls":["AC-2","AC-5","CM-3"],"is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(5)","oscal_id":"cm-5.5","family":"CM","title":"Privilege Limitation for Production and Operation","statement":"(a) Limit privileges to change system components and system-related information within a production or operational environment; and\n(b) Review and reevaluate privileges <organization-defined frequency>.","supplemental_guidance":"In many organizations, systems support multiple mission and business functions. Limiting privileges to change system components with respect to operational systems is necessary because changes to a system component may have far-reaching effects on mission and business processes supported by the system. The relationships between systems and mission/business processes are, in some cases, unknown to developers. System-related information includes operational procedures.","implementation_level":"organization","parameters":[{"id":"cm-5.5_prm_1","label":"organization-defined frequency"},{"id":"cm-05.05_odp.01","label":"frequency"},{"id":"cm-05.05_odp.02","label":"frequency"}],"objectives":[{"id":"cm-5.5_obj.a-1","label":"CM-05(05)(a)[01]","text":"privileges to change system components within a production or operational environment are limited;"},{"id":"cm-5.5_obj.a-2","label":"CM-05(05)(a)[02]","text":"privileges to change system-related information within a production or operational environment are limited;"},{"id":"cm-5.5_obj.b-1","label":"CM-05(05)(b)[01]","text":"privileges are reviewed {{ insert: param, cm-05.05_odp.01 }};"},{"id":"cm-5.5_obj.b-2","label":"CM-05(05)(b)[02]","text":"privileges are reevaluated {{ insert: param, cm-05.05_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-05(05)-Examine"},{"method":"interview","label":"CM-05(05)-Interview"},{"method":"test","label":"CM-05(05)-Test"}],"related_controls":["AC-2"],"is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(6)","oscal_id":"cm-5.6","family":"CM","title":"Limit Library Privileges","statement":"Limit privileges to change software resident within software libraries.","supplemental_guidance":"Software libraries include privileged programs.","implementation_level":"organization","methods":[{"method":"examine","label":"CM-05(06)-Examine"},{"method":"interview","label":"CM-05(06)-Interview"},{"method":"test","label":"CM-05(06)-Test"}],"related_controls":["AC-2"],"is_enhancement":true,"parent_id":"CM-5"},{"id":"CM-5(7)","oscal_id":"cm-5.7","family":"CM","title":"Automatic Implementation of Security Safeguards","statement":"","is_enhancement":true,"parent_id":"CM-5"}]},{"id":"CM-6","oscal_id":"cm-6","family":"CM","title":"Configuration Settings","statement":"a. Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using <common secure configurations>;\nb. Implement the configuration settings;\nc. Identify, document, and approve any deviations from established configuration settings for <system components> based on <operational requirements> ; and\nd. Monitor and control changes to the configuration settings in accordance with organizational policies and procedures.","supplemental_guidance":"Configuration settings are the parameters that can be changed in the hardware, software, or firmware components of the system that affect the security and privacy posture or functionality of the system. Information technology products for which configuration settings can be defined include mainframe computers, servers, workstations, operating systems, mobile devices, input/output devices, protocols, and applications. Parameters that impact the security posture of systems include registry settings; account, file, or directory permission settings; and settings for functions, protocols, ports, services, and remote connections. Privacy parameters are parameters impacting the privacy posture of systems, including the parameters required to satisfy other privacy controls. Privacy parameters include settings for access controls, data processing preferences, and processing and retention permissions. Organizations establish organization-wide configuration settings and subsequently derive specific configuration settings for systems. The established settings become part of the configuration baseline for the system.\n\nCommon secure configurations (also known as security configuration checklists, lockdown and hardening guides, and security reference guides) provide recognized, standardized, and established benchmarks that stipulate secure configuration settings for information technology products and platforms as well as instructions for configuring those products or platforms to meet operational requirements. Common secure configurations can be developed by a variety of organizations, including information technology product developers, manufacturers, vendors, federal agencies, consortia, academia, industry, and other organizations in the public and private sectors.\n\nImplementation of a common secure configuration may be mandated at the organization level, mission and business process level, system level, or at a higher level, including by a regulatory agency. Common secure configurations include the United States Government Configuration Baseline [USGCB](#98498928-3ca3-44b3-8b1e-f48685373087) and security technical implementation guides (STIGs), which affect the implementation of [CM-6](#cm-6) and other controls such as [AC-19](#ac-19) and [CM-7](#cm-7) . The Security Content Automation Protocol (SCAP) and the defined standards within the protocol provide an effective method to uniquely identify, track, and control configuration settings.","implementation_level":"organization","parameters":[{"id":"cm-06_odp.01","label":"common secure configurations"},{"id":"cm-06_odp.02","label":"system components"},{"id":"cm-06_odp.03","label":"operational requirements"}],"objectives":[{"id":"cm-6_obj.a","label":"CM-06a.","text":"configuration settings that reflect the most restrictive mode consistent with operational requirements are established and documented for components employed within the system using {{ insert: param, cm-06_odp.01 }};"},{"id":"cm-6_obj.b","label":"CM-06b.","text":"the configuration settings documented in CM-06a are implemented;"},{"id":"cm-6_obj.c-1","label":"CM-06c.[01]","text":"any deviations from established configuration settings for {{ insert: param, cm-06_odp.02 }} are identified and documented based on {{ insert: param, cm-06_odp.03 }};"},{"id":"cm-6_obj.c-2","label":"CM-06c.[02]","text":"any deviations from established configuration settings for {{ insert: param, cm-06_odp.02 }} are approved;"},{"id":"cm-6_obj.d-1","label":"CM-06d.[01]","text":"changes to the configuration settings are monitored in accordance with organizational policies and procedures;"},{"id":"cm-6_obj.d-2","label":"CM-06d.[02]","text":"changes to the configuration settings are controlled in accordance with organizational policies and procedures."}],"methods":[{"method":"examine","label":"CM-06-Examine"},{"method":"interview","label":"CM-06-Interview"},{"method":"test","label":"CM-06-Test"}],"references":[{"title":"SP 800-70"},{"title":"SP 800-126"},{"title":"SP 800-128"},{"title":"USGCB"},{"title":"NCPR"},{"title":"DOD STIG"}],"related_controls":["AC-3","AC-19","AU-2","AU-6","CA-9","CM-2","CM-3","CM-5","CM-7","CM-11","CP-7","CP-9","CP-10","IA-3","IA-5","PL-8","PL-9","RA-5","SA-4","SA-5","SA-8","SA-9","SC-18","SC-28","SC-43","SI-2","SI-4","SI-6"],"enhancements":[{"id":"CM-6(1)","oscal_id":"cm-6.1","family":"CM","title":"Automated Management, Application, and Verification","statement":"Manage, apply, and verify configuration settings for <system components> using <organization-defined automated mechanisms>.","supplemental_guidance":"Automated tools (e.g., hardening tools, baseline configuration tools) can improve the accuracy, consistency, and availability of configuration settings information. Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization.","implementation_level":"organization","parameters":[{"id":"cm-6.1_prm_2","label":"organization-defined automated mechanisms"},{"id":"cm-06.01_odp.01","label":"system components"},{"id":"cm-06.01_odp.02","label":"automated mechanisms"},{"id":"cm-06.01_odp.03","label":"automated mechanisms"},{"id":"cm-06.01_odp.04","label":"automated mechanisms"}],"objectives":[{"id":"cm-6.1_obj-1","label":"CM-06(01)[01]","text":"configuration settings for {{ insert: param, cm-06.01_odp.01 }} are managed using {{ insert: param, cm-06.01_odp.02 }};"},{"id":"cm-6.1_obj-2","label":"CM-06(01)[02]","text":"configuration settings for {{ insert: param, cm-06.01_odp.01 }} are applied using {{ insert: param, cm-06.01_odp.03 }};"},{"id":"cm-6.1_obj-3","label":"CM-06(01)[03]","text":"configuration settings for {{ insert: param, cm-06.01_odp.01 }} are verified using {{ insert: param, cm-06.01_odp.04 }}."}],"methods":[{"method":"examine","label":"CM-06(01)-Examine"},{"method":"interview","label":"CM-06(01)-Interview"},{"method":"test","label":"CM-06(01)-Test"}],"related_controls":["CA-7"],"is_enhancement":true,"parent_id":"CM-6"},{"id":"CM-6(2)","oscal_id":"cm-6.2","family":"CM","title":"Respond to Unauthorized Changes","statement":"Take the following actions in response to unauthorized changes to <configuration settings>: <actions>.","supplemental_guidance":"Responses to unauthorized changes to configuration settings include alerting designated organizational personnel, restoring established configuration settings, or—in extreme cases—halting affected system processing.","implementation_level":"organization","parameters":[{"id":"cm-06.02_odp.01","label":"actions"},{"id":"cm-06.02_odp.02","label":"configuration settings"}],"methods":[{"method":"examine","label":"CM-06(02)-Examine"},{"method":"interview","label":"CM-06(02)-Interview"},{"method":"test","label":"CM-06(02)-Test"}],"related_controls":["IR-4","IR-6","SI-7"],"is_enhancement":true,"parent_id":"CM-6"},{"id":"CM-6(3)","oscal_id":"cm-6.3","family":"CM","title":"Unauthorized Change Detection","statement":"","is_enhancement":true,"parent_id":"CM-6"},{"id":"CM-6(4)","oscal_id":"cm-6.4","family":"CM","title":"Conformance Demonstration","statement":"","is_enhancement":true,"parent_id":"CM-6"}]},{"id":"CM-7","oscal_id":"cm-7","family":"CM","title":"Least Functionality","statement":"a. Configure the system to provide only <mission-essential capabilities> ; and\nb. Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: <organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services>.","supplemental_guidance":"Systems provide a wide variety of functions and services. Some of the functions and services routinely provided by default may not be necessary to support essential organizational missions, functions, or operations. Additionally, it is sometimes convenient to provide multiple services from a single system component, but doing so increases risk over limiting the services provided by that single component. Where feasible, organizations limit component functionality to a single function per component. Organizations consider removing unused or unnecessary software and disabling unused or unnecessary physical and logical ports and protocols to prevent unauthorized connection of components, transfer of information, and tunneling. Organizations employ network scanning tools, intrusion detection and prevention systems, and end-point protection technologies, such as firewalls and host-based intrusion detection systems, to identify and prevent the use of prohibited functions, protocols, ports, and services. Least functionality can also be achieved as part of the fundamental design and development of the system (see [SA-8](#sa-8), [SC-2](#sc-2) , and [SC-3](#sc-3)).","implementation_level":"organization","parameters":[{"id":"cm-7_prm_2","label":"organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services"},{"id":"cm-07_odp.01","label":"mission-essential capabilities"},{"id":"cm-07_odp.02","label":"functions"},{"id":"cm-07_odp.03","label":"ports"},{"id":"cm-07_odp.04","label":"protocols"},{"id":"cm-07_odp.05","label":"software"},{"id":"cm-07_odp.06","label":"services"}],"objectives":[{"id":"cm-7_obj.a","label":"CM-07a.","text":"the system is configured to provide only {{ insert: param, cm-07_odp.01 }};"},{"id":"cm-7_obj.b-1","label":"CM-07b.[01]","text":"the use of {{ insert: param, cm-07_odp.02 }} is prohibited or restricted;"},{"id":"cm-7_obj.b-2","label":"CM-07b.[02]","text":"the use of {{ insert: param, cm-07_odp.03 }} is prohibited or restricted;"},{"id":"cm-7_obj.b-3","label":"CM-07b.[03]","text":"the use of {{ insert: param, cm-07_odp.04 }} is prohibited or restricted;"},{"id":"cm-7_obj.b-4","label":"CM-07b.[04]","text":"the use of {{ insert: param, cm-07_odp.05 }} is prohibited or restricted;"},{"id":"cm-7_obj.b-5","label":"CM-07b.[05]","text":"the use of {{ insert: param, cm-07_odp.06 }} is prohibited or restricted."}],"methods":[{"method":"examine","label":"CM-07-Examine"},{"method":"interview","label":"CM-07-Interview"},{"method":"test","label":"CM-07-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 180-4"},{"title":"FIPS 186-4"},{"title":"FIPS 202"},{"title":"SP 800-167"}],"related_controls":["AC-3","AC-4","CM-2","CM-5","CM-6","CM-11","RA-5","SA-4","SA-5","SA-8","SA-9","SA-15","SC-2","SC-3","SC-7","SC-37","SI-4"],"enhancements":[{"id":"CM-7(1)","oscal_id":"cm-7.1","family":"CM","title":"Periodic Review","statement":"(a) Review the system <frequency> to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and\n(b) Disable or remove <organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure>.","supplemental_guidance":"Organizations review functions, ports, protocols, and services provided by systems or system components to determine the functions and services that are candidates for elimination. Such reviews are especially important during transition periods from older technologies to newer technologies (e.g., transition from IPv4 to IPv6). These technology transitions may require implementing the older and newer technologies simultaneously during the transition period and returning to minimum essential functions, ports, protocols, and services at the earliest opportunity. Organizations can either decide the relative security of the function, port, protocol, and/or service or base the security decision on the assessment of other entities. Unsecure protocols include Bluetooth, FTP, and peer-to-peer networking.","implementation_level":"organization","parameters":[{"id":"cm-7.1_prm_2","label":"organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure"},{"id":"cm-07.01_odp.01","label":"frequency"},{"id":"cm-07.01_odp.02","label":"functions"},{"id":"cm-07.01_odp.03","label":"ports"},{"id":"cm-07.01_odp.04","label":"protocols"},{"id":"cm-07.01_odp.05","label":"software"},{"id":"cm-07.01_odp.06","label":"services"}],"objectives":[{"id":"cm-7.1_obj.a","label":"CM-07(01)(a)","text":"the system is reviewed {{ insert: param, cm-07.01_odp.01 }} to identify unnecessary and/or non-secure functions, ports, protocols, software, and services:"},{"id":"cm-7.1_obj.b-1","label":"CM-07(01)(b)[01]","text":"{{ insert: param, cm-07.01_odp.02 }} deemed to be unnecessary and/or non-secure are disabled or removed;"},{"id":"cm-7.1_obj.b-2","label":"CM-07(01)(b)[02]","text":"{{ insert: param, cm-07.01_odp.03 }} deemed to be unnecessary and/or non-secure are disabled or removed;"},{"id":"cm-7.1_obj.b-3","label":"CM-07(01)(b)[03]","text":"{{ insert: param, cm-07.01_odp.04 }} deemed to be unnecessary and/or non-secure are disabled or removed;"},{"id":"cm-7.1_obj.b-4","label":"CM-07(01)(b)[04]","text":"{{ insert: param, cm-07.01_odp.05 }} deemed to be unnecessary and/or non-secure is disabled or removed;"},{"id":"cm-7.1_obj.b-5","label":"CM-07(01)(b)[05]","text":"{{ insert: param, cm-07.01_odp.06 }} deemed to be unnecessary and/or non-secure are disabled or removed."}],"methods":[{"method":"examine","label":"CM-07(01)-Examine"},{"method":"interview","label":"CM-07(01)-Interview"},{"method":"test","label":"CM-07(01)-Test"}],"related_controls":["AC-18"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(2)","oscal_id":"cm-7.2","family":"CM","title":"Prevent Program Execution","statement":"Prevent program execution in accordance with <organization-defined parameter>.","supplemental_guidance":"Prevention of program execution addresses organizational policies, rules of behavior, and/or access agreements that restrict software usage and the terms and conditions imposed by the developer or manufacturer, including software licensing and copyrights. Restrictions include prohibiting auto-execute features, restricting roles allowed to approve program execution, permitting or prohibiting specific software programs, or restricting the number of program instances executed at the same time.","implementation_level":"system","parameters":[{"id":"cm-07.02_odp.01","label":"","choices":["{{ insert: param, cm-07.02_odp.02 }} ","rules authorizing the terms and conditions of software program usage"],"how_many":"one-or-more"},{"id":"cm-07.02_odp.02","label":"policies, rules of behavior, and/or access agreements regarding software program usage and restrictions"}],"methods":[{"method":"examine","label":"CM-07(02)-Examine"},{"method":"interview","label":"CM-07(02)-Interview"},{"method":"test","label":"CM-07(02)-Test"}],"related_controls":["CM-8","PL-4","PL-9","PM-5","PS-6"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(3)","oscal_id":"cm-7.3","family":"CM","title":"Registration Compliance","statement":"Ensure compliance with <registration requirements>.","supplemental_guidance":"Organizations use the registration process to manage, track, and provide oversight for systems and implemented functions, ports, protocols, and services.","implementation_level":"organization","parameters":[{"id":"cm-07.03_odp","label":"registration requirements"}],"methods":[{"method":"examine","label":"CM-07(03)-Examine"},{"method":"interview","label":"CM-07(03)-Interview"},{"method":"test","label":"CM-07(03)-Test"}],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(4)","oscal_id":"cm-7.4","family":"CM","title":"Unauthorized Software — Deny-by-exception","statement":"(a) Identify <software programs>;\n(b) Employ an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the system; and\n(c) Review and update the list of unauthorized software programs <frequency>.","supplemental_guidance":"Unauthorized software programs can be limited to specific versions or from a specific source. The concept of prohibiting the execution of unauthorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses.","implementation_level":"organization","parameters":[{"id":"cm-07.04_odp.01","label":"software programs"},{"id":"cm-07.04_odp.02","label":"frequency"}],"objectives":[{"id":"cm-7.4_obj.a","label":"CM-07(04)(a)","text":"{{ insert: param, cm-07.04_odp.01 }} are identified;"},{"id":"cm-7.4_obj.b","label":"CM-07(04)(b)","text":"an allow-all, deny-by-exception policy is employed to prohibit the execution of unauthorized software programs on the system;"},{"id":"cm-7.4_obj.c","label":"CM-07(04)(c)","text":"the list of unauthorized software programs is reviewed and updated {{ insert: param, cm-07.04_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-07(04)-Examine"},{"method":"interview","label":"CM-07(04)-Interview"},{"method":"test","label":"CM-07(04)-Test"}],"related_controls":["CM-6","CM-8","CM-10","PL-9","PM-5"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(5)","oscal_id":"cm-7.5","family":"CM","title":"Authorized Software — Allow-by-exception","statement":"(a) Identify <software programs>;\n(b) Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and\n(c) Review and update the list of authorized software programs <frequency>.","supplemental_guidance":"Authorized software programs can be limited to specific versions or from a specific source. To facilitate a comprehensive authorized software process and increase the strength of protection for attacks that bypass application level authorized software, software programs may be decomposed into and monitored at different levels of detail. These levels include applications, application programming interfaces, application modules, scripts, system processes, system services, kernel functions, registries, drivers, and dynamic link libraries. The concept of permitting the execution of authorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses. Organizations consider verifying the integrity of authorized software programs using digital signatures, cryptographic checksums, or hash functions. Verification of authorized software can occur either prior to execution or at system startup. The identification of authorized URLs for websites is addressed in [CA-3(5)](#ca-3.5) and [SC-7](#sc-7).","implementation_level":"organization","parameters":[{"id":"cm-07.05_odp.01","label":"software programs"},{"id":"cm-07.05_odp.02","label":"frequency"}],"objectives":[{"id":"cm-7.5_obj.a","label":"CM-07(05)(a)","text":"{{ insert: param, cm-07.05_odp.01 }} are identified;"},{"id":"cm-7.5_obj.b","label":"CM-07(05)(b)","text":"a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system is employed;"},{"id":"cm-7.5_obj.c","label":"CM-07(05)(c)","text":"the list of authorized software programs is reviewed and updated {{ insert: param, cm-07.05_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-07(05)-Examine"},{"method":"interview","label":"CM-07(05)-Interview"},{"method":"test","label":"CM-07(05)-Test"}],"related_controls":["CM-2","CM-6","CM-8","CM-10","PL-9","PM-5","SA-10","SC-34","SI-7"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(6)","oscal_id":"cm-7.6","family":"CM","title":"Confined Environments with Limited Privileges","statement":"Require that the following user-installed software execute in a confined physical or virtual machine environment with limited privileges: <user-installed software>.","supplemental_guidance":"Organizations identify software that may be of concern regarding its origin or potential for containing malicious code. For this type of software, user installations occur in confined environments of operation to limit or contain damage from malicious code that may be executed.","implementation_level":"organization","parameters":[{"id":"cm-07.06_odp","label":"user-installed software"}],"methods":[{"method":"examine","label":"CM-07(06)-Examine"},{"method":"interview","label":"CM-07(06)-Interview"},{"method":"test","label":"CM-07(06)-Test"}],"related_controls":["CM-11","SC-44"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(7)","oscal_id":"cm-7.7","family":"CM","title":"Code Execution in Protected Environments","statement":"Allow execution of binary or machine-executable code only in confined physical or virtual machine environments and with the explicit approval of <personnel or roles> when such code is:\n(a) Obtained from sources with limited or no warranty; and/or\n(b) Without the provision of source code.","supplemental_guidance":"Code execution in protected environments applies to all sources of binary or machine-executable code, including commercial software and firmware and open-source software.","implementation_level":"organization","parameters":[{"id":"cm-07.07_odp","label":"personnel or roles"}],"objectives":[{"id":"cm-7.7_obj.a","label":"CM-07(07)(a)","text":"the execution of binary or machine-executable code obtained from sources with limited or no warranty is only allowed with the explicit approval of {{ insert: param, cm-07.07_odp }};"},{"id":"cm-7.7_obj.b","label":"CM-07(07)(b)","text":"the execution of binary or machine-executable code without the provision of source code is only allowed with the explicit approval of {{ insert: param, cm-07.07_odp }}."}],"methods":[{"method":"examine","label":"CM-07(07)-Examine"},{"method":"interview","label":"CM-07(07)-Interview"},{"method":"test","label":"CM-07(07)-Test"}],"related_controls":["CM-10","SC-44"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(8)","oscal_id":"cm-7.8","family":"CM","title":"Binary or Machine Executable Code","statement":"(a) Prohibit the use of binary or machine-executable code from sources with limited or no warranty or without the provision of source code; and\n(b) Allow exceptions only for compelling mission or operational requirements and with the approval of the authorizing official.","supplemental_guidance":"Binary or machine executable code applies to all sources of binary or machine-executable code, including commercial software and firmware and open-source software. Organizations assess software products without accompanying source code or from sources with limited or no warranty for potential security impacts. The assessments address the fact that software products without the provision of source code may be difficult to review, repair, or extend. In addition, there may be no owners to make such repairs on behalf of organizations. If open-source software is used, the assessments address the fact that there is no warranty, the open-source software could contain back doors or malware, and there may be no support available.","implementation_level":"organization","objectives":[{"id":"cm-7.8_obj.a","label":"CM-07(08)(a)","text":"the use of binary or machine-executable code is prohibited when it originates from sources with limited or no warranty or without the provision of source code;"},{"id":"cm-7.8_obj.b-1","label":"CM-07(08)(b)[01]","text":"exceptions to the prohibition of binary or machine-executable code from sources with limited or no warranty or without the provision of source code are allowed only for compelling mission or operational requirements;"},{"id":"cm-7.8_obj.b-2","label":"CM-07(08)(b)[02]","text":"exceptions to the prohibition of binary or machine-executable code from sources with limited or no warranty or without the provision of source code are allowed only with the approval of the authorizing official."}],"methods":[{"method":"examine","label":"CM-07(08)-Examine"},{"method":"interview","label":"CM-07(08)-Interview"},{"method":"test","label":"CM-07(08)-Test"}],"related_controls":["SA-5","SA-22"],"is_enhancement":true,"parent_id":"CM-7"},{"id":"CM-7(9)","oscal_id":"cm-7.9","family":"CM","title":"Prohibiting The Use of Unauthorized Hardware","statement":"(a) Identify <hardware components>;\n(b) Prohibit the use or connection of unauthorized hardware components;\n(c) Review and update the list of authorized hardware components <frequency>.","supplemental_guidance":"Hardware components provide the foundation for organizational systems and the platform for the execution of authorized software programs. Managing the inventory of hardware components and controlling which hardware components are permitted to be installed or connected to organizational systems is essential in order to provide adequate security.","implementation_level":"organization","parameters":[{"id":"cm-07.09_odp.01","label":"hardware components"},{"id":"cm-07.09_odp.02","label":"frequency"}],"objectives":[{"id":"cm-7.9_obj.a","label":"CM-07(09)(a)","text":"{{ insert: param, cm-07.09_odp.01 }} are identified;"},{"id":"cm-7.9_obj.b","label":"CM-07(09)(b)","text":"the use or connection of unauthorized hardware components is prohibited;"},{"id":"cm-7.9_obj.c","label":"CM-07(09)(c)","text":"the list of authorized hardware components is reviewed and updated {{ insert: param, cm-07.09_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-07(09)-Examine"},{"method":"interview","label":"CM-07(09)-Interview"},{"method":"test","label":"CM-07(09)-Test"}],"is_enhancement":true,"parent_id":"CM-7"}]},{"id":"CM-8","oscal_id":"cm-8","family":"CM","title":"System Component Inventory","statement":"a. Develop and document an inventory of system components that:\n  Develop and document an inventory of system components that:\n  1. Accurately reflects the system;\n  2. Includes all components within the system;\n  3. Does not include duplicate accounting of components or components assigned to any other system;\n  4. Is at the level of granularity deemed necessary for tracking and reporting; and\n  5. Includes the following information to achieve system component accountability: <information> ; and\nb. Review and update the system component inventory <frequency>.","supplemental_guidance":"System components are discrete, identifiable information technology assets that include hardware, software, and firmware. Organizations may choose to implement centralized system component inventories that include components from all organizational systems. In such situations, organizations ensure that the inventories include system-specific information required for component accountability. The information necessary for effective accountability of system components includes the system name, software owners, software version numbers, hardware inventory specifications, software license information, and for networked components, the machine names and network addresses across all implemented protocols (e.g., IPv4, IPv6). Inventory specifications include date of receipt, cost, model, serial number, manufacturer, supplier information, component type, and physical location.\n\nPreventing duplicate accounting of system components addresses the lack of accountability that occurs when component ownership and system association is not known, especially in large or complex connected systems. Effective prevention of duplicate accounting of system components necessitates use of a unique identifier for each component. For software inventory, centrally managed software that is accessed via other systems is addressed as a component of the system on which it is installed and managed. Software installed on multiple organizational systems and managed at the system level is addressed for each individual system and may appear more than once in a centralized component inventory, necessitating a system association for each software instance in the centralized inventory to avoid duplicate accounting of components. Scanning systems implementing multiple network protocols (e.g., IPv4 and IPv6) can result in duplicate components being identified in different address spaces. The implementation of [CM-8(7)](#cm-8.7) can help to eliminate duplicate accounting of components.","implementation_level":"organization","parameters":[{"id":"cm-08_odp.01","label":"information"},{"id":"cm-08_odp.02","label":"frequency"}],"objectives":[{"id":"cm-8_obj.a.1","label":"CM-08a.01","text":"an inventory of system components that accurately reflects the system is developed and documented;"},{"id":"cm-8_obj.a.2","label":"CM-08a.02","text":"an inventory of system components that includes all components within the system is developed and documented;"},{"id":"cm-8_obj.a.3","label":"CM-08a.03","text":"an inventory of system components that does not include duplicate accounting of components or components assigned to any other system is developed and documented;"},{"id":"cm-8_obj.a.4","label":"CM-08a.04","text":"an inventory of system components that is at the level of granularity deemed necessary for tracking and reporting is developed and documented;"},{"id":"cm-8_obj.a.5","label":"CM-08a.05","text":"an inventory of system components that includes {{ insert: param, cm-08_odp.01 }} is developed and documented;"},{"id":"cm-8_obj.b","label":"CM-08b.","text":"the system component inventory is reviewed and updated {{ insert: param, cm-08_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-08-Examine"},{"method":"interview","label":"CM-08-Interview"},{"method":"test","label":"CM-08-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-128"},{"title":"IR 8011-2"},{"title":"IR 8011-3"}],"related_controls":["CM-2","CM-7","CM-9","CM-10","CM-11","CM-13","CP-2","CP-9","MA-2","MA-6","PE-20","PL-9","PM-5","SA-4","SA-5","SI-2","SR-4"],"enhancements":[{"id":"CM-8(1)","oscal_id":"cm-8.1","family":"CM","title":"Updates During Installation and Removal","statement":"Update the inventory of system components as part of component installations, removals, and system updates.","supplemental_guidance":"Organizations can improve the accuracy, completeness, and consistency of system component inventories if the inventories are updated as part of component installations or removals or during general system updates. If inventories are not updated at these key times, there is a greater likelihood that the information will not be appropriately captured and documented. System updates include hardware, software, and firmware components.","implementation_level":"organization","objectives":[{"id":"cm-8.1_obj-1","label":"CM-08(01)[01]","text":"the inventory of system components is updated as part of component installations;"},{"id":"cm-8.1_obj-2","label":"CM-08(01)[02]","text":"the inventory of system components is updated as part of component removals;"},{"id":"cm-8.1_obj-3","label":"CM-08(01)[03]","text":"the inventory of system components is updated as part of system updates."}],"methods":[{"method":"examine","label":"CM-08(01)-Examine"},{"method":"interview","label":"CM-08(01)-Interview"},{"method":"test","label":"CM-08(01)-Test"}],"related_controls":["PM-16"],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(2)","oscal_id":"cm-8.2","family":"CM","title":"Automated Maintenance","statement":"Maintain the currency, completeness, accuracy, and availability of the inventory of system components using <organization-defined automated mechanisms>.","supplemental_guidance":"Organizations maintain system inventories to the extent feasible. For example, virtual machines can be difficult to monitor because such machines are not visible to the network when not in use. In such cases, organizations maintain as up-to-date, complete, and accurate an inventory as is deemed reasonable. Automated maintenance can be achieved by the implementation of [CM-2(2)](#cm-2.2) for organizations that combine system component inventory and baseline configuration activities.","implementation_level":"organization","parameters":[{"id":"cm-8.2_prm_1","label":"organization-defined automated mechanisms"},{"id":"cm-08.02_odp.01","label":"automated mechanisms"},{"id":"cm-08.02_odp.02","label":"automated mechanisms"},{"id":"cm-08.02_odp.03","label":"automated mechanisms"},{"id":"cm-08.02_odp.04","label":"automated mechanisms"}],"objectives":[{"id":"cm-8.2_obj-1","label":"CM-08(02)[01]","text":"{{ insert: param, cm-08.02_odp.01 }} are used to maintain the currency of the system component inventory;"},{"id":"cm-8.2_obj-2","label":"CM-08(02)[02]","text":"{{ insert: param, cm-08.02_odp.02 }} are used to maintain the completeness of the system component inventory;"},{"id":"cm-8.2_obj-3","label":"CM-08(02)[03]","text":"{{ insert: param, cm-08.02_odp.03 }} are used to maintain the accuracy of the system component inventory;"},{"id":"cm-8.2_obj-4","label":"CM-08(02)[04]","text":"{{ insert: param, cm-08.02_odp.04 }} are used to maintain the availability of the system component inventory."}],"methods":[{"method":"examine","label":"CM-08(02)-Examine"},{"method":"interview","label":"CM-08(02)-Interview"},{"method":"test","label":"CM-08(02)-Test"}],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(3)","oscal_id":"cm-8.3","family":"CM","title":"Automated Unauthorized Component Detection","statement":"(a) Detect the presence of unauthorized hardware, software, and firmware components within the system using <organization-defined automated mechanisms> <frequency> ; and\n(b) Take the following actions when unauthorized components are detected: <organization-defined parameter>.","supplemental_guidance":"Automated unauthorized component detection is applied in addition to the monitoring for unauthorized remote connections and mobile devices. Monitoring for unauthorized system components may be accomplished on an ongoing basis or by the periodic scanning of systems for that purpose. Automated mechanisms may also be used to prevent the connection of unauthorized components (see [CM-7(9)](#cm-7.9) ). Automated mechanisms can be implemented in systems or in separate system components. When acquiring and implementing automated mechanisms, organizations consider whether such mechanisms depend on the ability of the system component to support an agent or supplicant in order to be detected since some types of components do not have or cannot support agents (e.g., IoT devices, sensors). Isolation can be achieved , for example, by placing unauthorized system components in separate domains or subnets or quarantining such components. This type of component isolation is commonly referred to as \"sandboxing.\"","implementation_level":"organization","parameters":[{"id":"cm-8.3_prm_1","label":"organization-defined automated mechanisms"},{"id":"cm-08.03_odp.01","label":"automated mechanisms"},{"id":"cm-08.03_odp.02","label":"automated mechanisms"},{"id":"cm-08.03_odp.03","label":"automated mechanisms"},{"id":"cm-08.03_odp.04","label":"frequency"},{"id":"cm-08.03_odp.05","label":"","choices":["disable network access by unauthorized components","isolate unauthorized components","notify {{ insert: param, cm-08.03_odp.06 }} "],"how_many":"one-or-more"},{"id":"cm-08.03_odp.06","label":"personnel or roles"}],"objectives":[{"id":"cm-8.3_obj.a-1","label":"CM-08(03)(a)[01]","text":"the presence of unauthorized hardware within the system is detected using {{ insert: param, cm-08.03_odp.01 }} {{ insert: param, cm-08.03_odp.04 }};"},{"id":"cm-8.3_obj.a-2","label":"CM-08(03)(a)[02]","text":"the presence of unauthorized software within the system is detected using {{ insert: param, cm-08.03_odp.02 }} {{ insert: param, cm-08.03_odp.04 }};"},{"id":"cm-8.3_obj.a-3","label":"CM-08(03)(a)[03]","text":"the presence of unauthorized firmware within the system is detected using {{ insert: param, cm-08.03_odp.03 }} {{ insert: param, cm-08.03_odp.04 }};"},{"id":"cm-8.3_obj.b-1","label":"CM-08(03)(b)[01]","text":"{{ insert: param, cm-08.03_odp.05 }} are taken when unauthorized hardware is detected;"},{"id":"cm-8.3_obj.b-2","label":"CM-08(03)(b)[02]","text":"{{ insert: param, cm-08.03_odp.05 }} are taken when unauthorized software is detected;"},{"id":"cm-8.3_obj.b-3","label":"CM-08(03)(b)[03]","text":"{{ insert: param, cm-08.03_odp.05 }} are taken when unauthorized firmware is detected."}],"methods":[{"method":"examine","label":"CM-08(03)-Examine"},{"method":"interview","label":"CM-08(03)-Interview"},{"method":"test","label":"CM-08(03)-Test"}],"related_controls":["AC-19","CA-7","RA-5","SC-3","SC-39","SC-44","SI-3","SI-4","SI-7"],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(4)","oscal_id":"cm-8.4","family":"CM","title":"Accountability Information","statement":"Include in the system component inventory information, a means for identifying by <organization-defined parameter> , individuals responsible and accountable for administering those components.","supplemental_guidance":"Identifying individuals who are responsible and accountable for administering system components ensures that the assigned components are properly administered and that organizations can contact those individuals if some action is required (e.g., when the component is determined to be the source of a breach, needs to be recalled or replaced, or needs to be relocated).","implementation_level":"organization","parameters":[{"id":"cm-08.04_odp","label":"","choices":["name","position","role"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"CM-08(04)-Examine"},{"method":"interview","label":"CM-08(04)-Interview"},{"method":"test","label":"CM-08(04)-Test"}],"related_controls":["AC-3"],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(5)","oscal_id":"cm-8.5","family":"CM","title":"No Duplicate Accounting of Components","statement":"","is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(6)","oscal_id":"cm-8.6","family":"CM","title":"Assessed Configurations and Approved Deviations","statement":"Include assessed component configurations and any approved deviations to current deployed configurations in the system component inventory.","supplemental_guidance":"Assessed configurations and approved deviations focus on configuration settings established by organizations for system components, the specific components that have been assessed to determine compliance with the required configuration settings, and any approved deviations from established configuration settings.","implementation_level":"organization","objectives":[{"id":"cm-8.6_obj-1","label":"CM-08(06)[01]","text":"assessed component configurations are included in the system component inventory;"},{"id":"cm-8.6_obj-2","label":"CM-08(06)[02]","text":"any approved deviations to current deployed configurations are included in the system component inventory."}],"methods":[{"method":"examine","label":"CM-08(06)-Examine"},{"method":"interview","label":"CM-08(06)-Interview"},{"method":"test","label":"CM-08(06)-Test"}],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(7)","oscal_id":"cm-8.7","family":"CM","title":"Centralized Repository","statement":"Provide a centralized repository for the inventory of system components.","supplemental_guidance":"Organizations may implement centralized system component inventories that include components from all organizational systems. Centralized repositories of component inventories provide opportunities for efficiencies in accounting for organizational hardware, software, and firmware assets. Such repositories may also help organizations rapidly identify the location and responsible individuals of components that have been compromised, breached, or are otherwise in need of mitigation actions. Organizations ensure that the resulting centralized inventories include system-specific information required for proper component accountability.","implementation_level":"organization","methods":[{"method":"examine","label":"CM-08(07)-Examine"},{"method":"interview","label":"CM-08(07)-Interview"},{"method":"test","label":"CM-08(07)-Test"}],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(8)","oscal_id":"cm-8.8","family":"CM","title":"Automated Location Tracking","statement":"Support the tracking of system components by geographic location using <automated mechanisms>.","supplemental_guidance":"The use of automated mechanisms to track the location of system components can increase the accuracy of component inventories. Such capability may help organizations rapidly identify the location and responsible individuals of system components that have been compromised, breached, or are otherwise in need of mitigation actions. The use of tracking mechanisms can be coordinated with senior agency officials for privacy if there are implications that affect individual privacy.","implementation_level":"organization","parameters":[{"id":"cm-08.08_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"CM-08(08)-Examine"},{"method":"interview","label":"CM-08(08)-Interview"},{"method":"test","label":"CM-08(08)-Test"}],"is_enhancement":true,"parent_id":"CM-8"},{"id":"CM-8(9)","oscal_id":"cm-8.9","family":"CM","title":"Assignment of Components to Systems","statement":"(a) Assign system components to a system; and\n(b) Receive an acknowledgement from <personnel or roles> of this assignment.","supplemental_guidance":"System components that are not assigned to a system may be unmanaged, lack the required protection, and become an organizational vulnerability.","implementation_level":"organization","parameters":[{"id":"cm-08.09_odp","label":"personnel or roles"}],"objectives":[{"id":"cm-8.9_obj.a","label":"CM-08(09)(a)","text":"system components are assigned to a system;"},{"id":"cm-8.9_obj.b","label":"CM-08(09)(b)","text":"an acknowledgement of the component assignment is received from {{ insert: param, cm-08.09_odp }}."}],"methods":[{"method":"examine","label":"CM-08(09)-Examine"},{"method":"interview","label":"CM-08(09)-Interview"},{"method":"test","label":"CM-08(09)-Test"}],"is_enhancement":true,"parent_id":"CM-8"}]},{"id":"CM-9","oscal_id":"cm-9","family":"CM","title":"Configuration Management Plan","statement":"Develop, document, and implement a configuration management plan for the system that:\na. Addresses roles, responsibilities, and configuration management processes and procedures;\nb. Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items;\nc. Defines the configuration items for the system and places the configuration items under configuration management;\nd. Is reviewed and approved by <personnel or roles> ; and\ne. Protects the configuration management plan from unauthorized disclosure and modification.","supplemental_guidance":"Configuration management activities occur throughout the system development life cycle. As such, there are developmental configuration management activities (e.g., the control of code and software libraries) and operational configuration management activities (e.g., control of installed components and how the components are configured). Configuration management plans satisfy the requirements in configuration management policies while being tailored to individual systems. Configuration management plans define processes and procedures for how configuration management is used to support system development life cycle activities.\n\nConfiguration management plans are generated during the development and acquisition stage of the system development life cycle. The plans describe how to advance changes through change management processes; update configuration settings and baselines; maintain component inventories; control development, test, and operational environments; and develop, release, and update key documents.\n\nOrganizations can employ templates to help ensure the consistent and timely development and implementation of configuration management plans. Templates can represent a configuration management plan for the organization with subsets of the plan implemented on a system by system basis. Configuration management approval processes include the designation of key stakeholders responsible for reviewing and approving proposed changes to systems, and personnel who conduct security and privacy impact analyses prior to the implementation of changes to the systems. Configuration items are the system components, such as the hardware, software, firmware, and documentation to be configuration-managed. As systems continue through the system development life cycle, new configuration items may be identified, and some existing configuration items may no longer need to be under configuration control.","implementation_level":"organization","parameters":[{"id":"cm-09_odp","label":"personnel or roles"}],"objectives":[{"id":"cm-9_obj-1","label":"CM-09[01]","text":"a configuration management plan for the system is developed and documented;"},{"id":"cm-9_obj-2","label":"CM-09[02]","text":"a configuration management plan for the system is implemented;"},{"id":"cm-9_obj.a-1","label":"CM-09a.[01]","text":"the configuration management plan addresses roles;"},{"id":"cm-9_obj.a-2","label":"CM-09a.[02]","text":"the configuration management plan addresses responsibilities;"},{"id":"cm-9_obj.a-3","label":"CM-09a.[03]","text":"the configuration management plan addresses configuration management processes and procedures;"},{"id":"cm-9_obj.b-1","label":"CM-09b.[01]","text":"the configuration management plan establishes a process for identifying configuration items throughout the system development life cycle;"},{"id":"cm-9_obj.b-2","label":"CM-09b.[02]","text":"the configuration management plan establishes a process for managing the configuration of the configuration items;"},{"id":"cm-9_obj.c-1","label":"CM-09c.[01]","text":"the configuration management plan defines the configuration items for the system;"},{"id":"cm-9_obj.c-2","label":"CM-09c.[02]","text":"the configuration management plan places the configuration items under configuration management;"},{"id":"cm-9_obj.d","label":"CM-09d.","text":"the configuration management plan is reviewed and approved by {{ insert: param, cm-09_odp }};"},{"id":"cm-9_obj.e-1","label":"CM-09e.[01]","text":"the configuration management plan is protected from unauthorized disclosure;"},{"id":"cm-9_obj.e-2","label":"CM-09e.[02]","text":"the configuration management plan is protected from unauthorized modification."}],"methods":[{"method":"examine","label":"CM-09-Examine"},{"method":"interview","label":"CM-09-Interview"},{"method":"test","label":"CM-09-Test"}],"references":[{"title":"SP 800-128"}],"related_controls":["CM-2","CM-3","CM-4","CM-5","CM-8","PL-2","RA-8","SA-10","SI-12"],"enhancements":[{"id":"CM-9(1)","oscal_id":"cm-9.1","family":"CM","title":"Assignment of Responsibility","statement":"Assign responsibility for developing the configuration management process to organizational personnel that are not directly involved in system development.","supplemental_guidance":"In the absence of dedicated configuration management teams assigned within organizations, system developers may be tasked with developing configuration management processes using personnel who are not directly involved in system development or system integration. This separation of duties ensures that organizations establish and maintain a sufficient degree of independence between the system development and integration processes and configuration management processes to facilitate quality control and more effective oversight.","implementation_level":"organization","methods":[{"method":"examine","label":"CM-09(01)-Examine"},{"method":"interview","label":"CM-09(01)-Interview"}],"is_enhancement":true,"parent_id":"CM-9"}]},{"id":"CM-10","oscal_id":"cm-10","family":"CM","title":"Software Usage Restrictions","statement":"a. Use software and associated documentation in accordance with contract agreements and copyright laws;\nb. Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; and\nc. Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work.","supplemental_guidance":"Software license tracking can be accomplished by manual or automated methods, depending on organizational needs. Examples of contract agreements include software license agreements and non-disclosure agreements.","implementation_level":"organization","objectives":[{"id":"cm-10_obj.a","label":"CM-10a.","text":"software and associated documentation are used in accordance with contract agreements and copyright laws;"},{"id":"cm-10_obj.b","label":"CM-10b.","text":"the use of software and associated documentation protected by quantity licenses is tracked to control copying and distribution;"},{"id":"cm-10_obj.c","label":"CM-10c.","text":"the use of peer-to-peer file sharing technology is controlled and documented to ensure that peer-to-peer file sharing is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work."}],"methods":[{"method":"examine","label":"CM-10-Examine"},{"method":"interview","label":"CM-10-Interview"},{"method":"test","label":"CM-10-Test"}],"related_controls":["AC-17","AU-6","CM-7","CM-8","PM-30","SC-7"],"enhancements":[{"id":"CM-10(1)","oscal_id":"cm-10.1","family":"CM","title":"Open-source Software","statement":"Establish the following restrictions on the use of open-source software: <restrictions>.","supplemental_guidance":"Open-source software refers to software that is available in source code form. Certain software rights normally reserved for copyright holders are routinely provided under software license agreements that permit individuals to study, change, and improve the software. From a security perspective, the major advantage of open-source software is that it provides organizations with the ability to examine the source code. In some cases, there is an online community associated with the software that inspects, tests, updates, and reports on issues found in software on an ongoing basis. However, remediating vulnerabilities in open-source software may be problematic. There may also be licensing issues associated with open-source software, including the constraints on derivative use of such software. Open-source software that is available only in binary form may increase the level of risk in using such software.","implementation_level":"organization","parameters":[{"id":"cm-10.01_odp","label":"restrictions"}],"methods":[{"method":"examine","label":"CM-10(01)-Examine"},{"method":"interview","label":"CM-10(01)-Interview"},{"method":"test","label":"CM-10(01)-Test"}],"related_controls":["SI-7"],"is_enhancement":true,"parent_id":"CM-10"}]},{"id":"CM-11","oscal_id":"cm-11","family":"CM","title":"User-installed Software","statement":"a. Establish <policies> governing the installation of software by users;\nb. Enforce software installation policies through the following methods: <methods> ; and\nc. Monitor policy compliance <frequency>.","supplemental_guidance":"If provided the necessary privileges, users can install software in organizational systems. To maintain control over the software installed, organizations identify permitted and prohibited actions regarding software installation. Permitted software installations include updates and security patches to existing software and downloading new applications from organization-approved \"app stores.\" Prohibited software installations include software with unknown or suspect pedigrees or software that organizations consider potentially malicious. Policies selected for governing user-installed software are organization-developed or provided by some external entity. Policy enforcement methods can include procedural methods and automated methods.","implementation_level":"organization","parameters":[{"id":"cm-11_odp.01","label":"policies"},{"id":"cm-11_odp.02","label":"methods"},{"id":"cm-11_odp.03","label":"frequency"}],"objectives":[{"id":"cm-11_obj.a","label":"CM-11a.","text":"{{ insert: param, cm-11_odp.01 }} governing the installation of software by users are established;"},{"id":"cm-11_obj.b","label":"CM-11b.","text":"software installation policies are enforced through {{ insert: param, cm-11_odp.02 }};"},{"id":"cm-11_obj.c","label":"CM-11c.","text":"compliance with {{ insert: param, cm-11_odp.01 }} is monitored {{ insert: param, cm-11_odp.03 }}."}],"methods":[{"method":"examine","label":"CM-11-Examine"},{"method":"interview","label":"CM-11-Interview"},{"method":"test","label":"CM-11-Test"}],"related_controls":["AC-3","AU-6","CM-2","CM-3","CM-5","CM-6","CM-7","CM-8","PL-4","SI-4","SI-7"],"enhancements":[{"id":"CM-11(1)","oscal_id":"cm-11.1","family":"CM","title":"Alerts for Unauthorized Installations","statement":"","is_enhancement":true,"parent_id":"CM-11"},{"id":"CM-11(2)","oscal_id":"cm-11.2","family":"CM","title":"Software Installation with Privileged Status","statement":"Allow user installation of software only with explicit privileged status.","supplemental_guidance":"Privileged status can be obtained, for example, by serving in the role of system administrator.","implementation_level":"system","methods":[{"method":"examine","label":"CM-11(02)-Examine"},{"method":"interview","label":"CM-11(02)-Interview"},{"method":"test","label":"CM-11(02)-Test"}],"related_controls":["AC-5","AC-6"],"is_enhancement":true,"parent_id":"CM-11"},{"id":"CM-11(3)","oscal_id":"cm-11.3","family":"CM","title":"Automated Enforcement and Monitoring","statement":"Enforce and monitor compliance with software installation policies using <organization-defined automated mechanisms>.","supplemental_guidance":"Organizations enforce and monitor compliance with software installation policies using automated mechanisms to more quickly detect and respond to unauthorized software installation which can be an indicator of an internal or external hostile attack.","implementation_level":"system","parameters":[{"id":"cm-11.3_prm_1","label":"organization-defined automated mechanisms"},{"id":"cm-11.03_odp.01","label":"automated mechanisms"},{"id":"cm-11.03_odp.02","label":"automated mechanisms"}],"objectives":[{"id":"cm-11.3_obj-1","label":"CM-11(03)[01]","text":"compliance with software installation policies is enforced using {{ insert: param, cm-11.03_odp.01 }};"},{"id":"cm-11.3_obj-2","label":"CM-11(03)[02]","text":"compliance with software installation policies is monitored using {{ insert: param, cm-11.03_odp.02 }}."}],"methods":[{"method":"examine","label":"CM-11(03)-Examine"},{"method":"interview","label":"CM-11(03)-Interview"},{"method":"test","label":"CM-11(03)-Test"}],"is_enhancement":true,"parent_id":"CM-11"}]},{"id":"CM-12","oscal_id":"cm-12","family":"CM","title":"Information Location","statement":"a. Identify and document the location of <information> and the specific system components on which the information is processed and stored;\nb. Identify and document the users who have access to the system and system components where the information is processed and stored; and\nc. Document changes to the location (i.e., system or system components) where the information is processed and stored.","supplemental_guidance":"Information location addresses the need to understand where information is being processed and stored. Information location includes identifying where specific information types and information reside in system components and how information is being processed so that information flow can be understood and adequate protection and policy management provided for such information and system components. The security category of the information is also a factor in determining the controls necessary to protect the information and the system component where the information resides (see [FIPS 199](#628d22a1-6a11-4784-bc59-5cd9497b5445) ). The location of the information and system components is also a factor in the architecture and design of the system (see [SA-4](#sa-4), [SA-8](#sa-8), [SA-17](#sa-17)).","implementation_level":"organization","parameters":[{"id":"cm-12_odp","label":"information"}],"objectives":[{"id":"cm-12_obj.a-1","label":"CM-12a.[01]","text":"the location of {{ insert: param, cm-12_odp }} is identified and documented;"},{"id":"cm-12_obj.a-2","label":"CM-12a.[02]","text":"the specific system components on which {{ insert: param, cm-12_odp }} is processed are identified and documented;"},{"id":"cm-12_obj.a-3","label":"CM-12a.[03]","text":"the specific system components on which {{ insert: param, cm-12_odp }} is stored are identified and documented;"},{"id":"cm-12_obj.b-1","label":"CM-12b.[01]","text":"the users who have access to the system and system components where {{ insert: param, cm-12_odp }} is processed are identified and documented;"},{"id":"cm-12_obj.b-2","label":"CM-12b.[02]","text":"the users who have access to the system and system components where {{ insert: param, cm-12_odp }} is stored are identified and documented;"},{"id":"cm-12_obj.c-1","label":"CM-12c.[01]","text":"changes to the location (i.e., system or system components) where {{ insert: param, cm-12_odp }} is processed are documented;"},{"id":"cm-12_obj.c-2","label":"CM-12c.[02]","text":"changes to the location (i.e., system or system components) where {{ insert: param, cm-12_odp }} is stored are documented."}],"methods":[{"method":"examine","label":"CM-12-Examine"},{"method":"interview","label":"CM-12-Interview"},{"method":"test","label":"CM-12-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-60-1"},{"title":"SP 800-60-2"}],"related_controls":["AC-2","AC-3","AC-4","AC-6","AC-23","CM-8","PM-5","RA-2","SA-4","SA-8","SA-17","SC-4","SC-16","SC-28","SI-4","SI-7"],"enhancements":[{"id":"CM-12(1)","oscal_id":"cm-12.1","family":"CM","title":"Automated Tools to Support Information Location","statement":"Use automated tools to identify <information by information type> on <system components> to ensure controls are in place to protect organizational information and individual privacy.","supplemental_guidance":"The use of automated tools helps to increase the effectiveness and efficiency of the information location capability implemented within the system. Automation also helps organizations manage the data produced during information location activities and share such information across the organization. The output of automated information location tools can be used to guide and inform system architecture and design decisions.","implementation_level":"organization","parameters":[{"id":"cm-12.01_odp.01","label":"information by information type"},{"id":"cm-12.01_odp.02","label":"system components"}],"methods":[{"method":"examine","label":"CM-12(01)-Examine"},{"method":"interview","label":"CM-12(01)-Interview"},{"method":"test","label":"CM-12(01)-Test"}],"is_enhancement":true,"parent_id":"CM-12"}]},{"id":"CM-13","oscal_id":"cm-13","family":"CM","title":"Data Action Mapping","statement":"Develop and document a map of system data actions.","supplemental_guidance":"Data actions are system operations that process personally identifiable information. The processing of such information encompasses the full information life cycle, which includes collection, generation, transformation, use, disclosure, retention, and disposal. A map of system data actions includes discrete data actions, elements of personally identifiable information being processed in the data actions, system components involved in the data actions, and the owners or operators of the system components. Understanding what personally identifiable information is being processed (e.g., the sensitivity of the personally identifiable information), how personally identifiable information is being processed (e.g., if the data action is visible to the individual or is processed in another part of the system), and by whom (e.g., individuals may have different privacy perceptions based on the entity that is processing the personally identifiable information) provides a number of contextual factors that are important to assessing the degree of privacy risk created by the system. Data maps can be illustrated in different ways, and the level of detail may vary based on the mission and business needs of the organization. The data map may be an overlay of any system design artifact that the organization is using. The development of this map may necessitate coordination between the privacy and security programs regarding the covered data actions and the components that are identified as part of the system.","implementation_level":"organization","methods":[{"method":"examine","label":"CM-13-Examine"},{"method":"interview","label":"CM-13-Interview"},{"method":"test","label":"CM-13-Test"}],"related_controls":["AC-3","CM-4","CM-12","PM-5","PM-27","PT-2","PT-3","RA-3","RA-8"]},{"id":"CM-14","oscal_id":"cm-14","family":"CM","title":"Signed Components","statement":"Prevent the installation of <organization-defined software and firmware components> without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.","supplemental_guidance":"Software and firmware components prevented from installation unless signed with recognized and approved certificates include software and firmware version updates, patches, service packs, device drivers, and basic input/output system updates. Organizations can identify applicable software and firmware components by type, by specific items, or a combination of both. Digital signatures and organizational verification of such signatures is a method of code authentication.","implementation_level":"organization","parameters":[{"id":"cm-14_prm_1","label":"organization-defined software and firmware components"},{"id":"cm-14_odp.01","label":"software components"},{"id":"cm-14_odp.02","label":"firmware components"}],"objectives":[{"id":"cm-14_obj-1","label":"CM-14[01]","text":"the installation of {{ insert: param, cm-14_odp.01 }} is prevented unless it is verified that the software has been digitally signed using a certificate recognized and approved by the organization;"},{"id":"cm-14_obj-2","label":"CM-14[02]","text":"the installation of {{ insert: param, cm-14_odp.02 }} is prevented unless it is verified that the firmware has been digitally signed using a certificate recognized and approved by the organization."}],"methods":[{"method":"examine","label":"CM-14-Examine"},{"method":"interview","label":"CM-14-Interview"},{"method":"test","label":"CM-14-Test"}],"references":[{"title":"IR 8062"}],"related_controls":["CM-7","SC-12","SC-13","SI-7"]}]};
